1:function triggerSeasonRollover(?int $targetSeasonNumber = null, bool $force = false): bool
2:{
3:    // Prevent automated season rollover while maintenance mode is active, unless explicitly forced
4:    if (!$force && isMaintenanceMode()) {
5:        log_message('notice', 'Season rollover blocked because maintenance mode is active.');
6:        return false;
7:    }
9:    $db = db_connect();
10:    if (!$db->tableExists('seasons')) return false;
12:    $curr = $db->table('seasons')->where('active', 1)->orderBy('season_number', 'DESC')->get()->getRowArray();
13:    $currSeasonNumber = (int) ($curr['season_number'] ?? 1);
15:    // Find next planned season
16:    $query = $db->table('seasons')->where('active', 0);
17:    if ($targetSeasonNumber !== null) {
18:        $query->where('season_number', $targetSeasonNumber);
19:    } else {
20:        $query->where('season_number >', $currSeasonNumber)->orderBy('season_number', 'ASC');
21:    }
22:    $nextSeason = $query->get()->getRowArray();
23:    if (!$nextSeason) {
24:        return false;
25:    }
27:    // Weather rows are keyed only by game_day, which restarts at 1 each season. Without this,
28:    // the new season would read last season's rows and the tick would skip days that "exist".
29:    // DDL commits implicitly in MySQL, so the archive table is created before the transaction.
30:    $weatherArchive = 'weather_season_' . $currSeasonNumber;
31:    if ($db->tableExists('weather')) {
32:        $db->query("CREATE TABLE IF NOT EXISTS `{$weatherArchive}` LIKE `weather`");
33:    }
35:    try {
36:        $db->transStart();
