39:        if ($db->tableExists('weather')) {
40:            $latest = $db->table('weather')->orderBy('game_day', 'DESC')->limit(1)->get()->getRowArray();
41:            if ($db->table($weatherArchive)->countAllResults() === 0) {
42:                $db->query("INSERT INTO `{$weatherArchive}` SELECT * FROM `weather`");
43:            }
44:            $db->table('weather')->emptyTable();
45:            if ($latest) {
46:                unset($latest['id']);
47:                $latest['game_day']   = 1;
48:                $latest['created_at'] = date('Y-m-d H:i:s');
49:                if (array_key_exists('updated_at', $latest)) $latest['updated_at'] = null;
50:                $db->table('weather')->insert($latest);
51:            }
52:        }
54:        // 1. Snapshot current leaderboard standings into archives
55:        if ($db->tableExists('season_leaderboard_archives')) {
56:            $alreadyArchived = $db->table('season_leaderboard_archives')
