58:                ->countAllResults();
60:            if ($alreadyArchived === 0) {
61:                $now = date('Y-m-d H:i:s');
62:                // resort_name lives on player_finances (users has no such column)
63:                $resortNameCol = $db->fieldExists('resort_name', 'player_finances') ? ', player_finances.resort_name' : '';
64:                $leaders = $db->table('player_finances')
65:                    ->select('player_finances.user_id, player_finances.cash, player_finances.reputation, users.username' . $resortNameCol)
66:                    ->join('users', 'users.id = player_finances.user_id')
67:                    ->where('users.id !=', 1)
68:                    // Demo accounts (status 'demo') shouldn't take podium/top-10 rewards; normal users have NULL status
69:                    ->groupStart()->where('users.status IS NULL')->orWhere('users.status !=', 'demo')->groupEnd()
70:                    ->orderBy('player_finances.cash', 'DESC')
71:                    ->limit(100)
72:                    ->get()->getResultArray();
74:                $archiveBatch = [];
