79:                    $liftsCount = $db->table('player_items')->where('user_id', $uId)->where('item_type', 'lift')->countAllResults();
81:                    $badge = ($rank <= 3) ? "Podium Champion (Rank #{$rank})" : (($rank <= 10) ? "Top 10 Season Pioneer" : "Season 1 Pioneer");
83:                    $archiveBatch[] = [
