P, fin, LVL = g["P"], g["fin"], g["LVL"]
ticket_terms, SHARE, LIFT_RUN, SLOPE_RUN = g["ticket_terms"], g["SHARE"], g["LIFT_RUN"], g["SLOPE_RUN"]
DIFF = g["DIFF"]
lt = {int(r["user_id"]): json.loads(r["last_tick"]) for r in csv.DictReader(open("stg/lt.tsv"), delimiter="\t")}
tourn = {}
for r in csv.DictReader(open("stg/tourn.tsv"), delimiter="\t"):
    if int(r["start_day"]) <= 3 <= int(r["end_day"]): tourn[int(r["user_id"])] = tourn.get(int(r["user_id"]),0) + int(r["visitors_boost"])
bad = 0; checked = 0
for u, t in sorted(lt.items()):
    p = P[u]; f = fin[u]; rm, cm, vm = DIFF.get(f["difficulty"], DIFF["standard"])
    # ticket terms (sim version had no SWITCH_TICKET; recompute with it)
    rows = p["tickets"]
    act = {x["ticket_type"]: int(x["price"]) for x in rows if x["active"]=="1"} if rows else dict(g["REF"])
    MIX, REF, VIS = g["MIX"], g["REF"], g["VISITS"]
    if act:
        S_ = sum(MIX[k] for k in act); sc = 1 + 0.5*(1-S_)/S_
        w = {k: MIX[k]*sc*min(1.5, math.exp(-0.9*(act[k]/REF[k]-1))) for k in act}
        dm = sum(w.values()); pv = sum(w[k]*act[k]/VIS.get(k,1) for k in act)/dm if dm else 0
    else: dm = pv = 0
