    cap = round(sum(int(l["capacity"]) or 2400 for l in lifts)*0.6) if lifts else 100
    exp_vis = 0 if f["open"]=="0" else min(round(t["demand"]*dm) + tourn.get(u,0), cap)
    exp_tix = round(round(exp_vis*pv)*rm)
