    bs = [b for b in p["bld"] if b["status"]=="open"]
    caps, cnt = {}, {}
    for b in bs:
        typ=b["building_type"]; caps[typ]=caps.get(typ,0)+max(1,int(LVL[(typ,int(b["level"]))]["capacity"])); cnt[typ]=cnt.get(typ,0)+1
    a = {}
    for s_ in p["staff"]:
        if s_["assigned"]=="1": a[s_["role"]] = a.get(s_["role"],0)+1
    rev = 0
    for b in bs:
        typ=b["building_type"]; util=min(1, t["visitors"]*SHARE.get(typ,0)/caps[typ]) if typ!="ski_patrol" else 0
        bonus = 1
        if typ=="hotel": bonus = 1+0.15*min(1,a.get("receptionist",0)/cnt[typ])
        if typ=="restaurant": bonus = 1+0.15*min(1,a.get("chef",0)/cnt[typ])
        rev += int(b["revenue_per_day"])*util*bonus
    exp_bld = 0 if f["open"]=="0" else round(rev*rm)
    run = sum(int(i["length_meters"])*LIFT_RUN.get(i["subtype"],0.8)*(1 if i["status"]=="open" else 0.2) for i in p["items"] if i["item_type"]=="lift" and i["status"] in ("open","closed")) + sum(int(i["length_meters"])*SLOPE_RUN for i in p["items"] if i["item_type"]=="slope" and i["status"]=="open")
    exp_run = round(run*cm)
    checks = {"visitors": (t["visitors"], exp_vis), "tickets": (t["tickets"], exp_tix), "buildings": (t["buildings"], exp_bld), "running": (t["lift_slope_running"], exp_run), "cap": (t["lift_capacity"], cap)}
    checked += 1
    off = {k: v for k, v in checks.items() if abs(v[0]-v[1]) > max(2, 0.01*abs(v[1]))}
    if off: bad += 1; print("MISMATCH", u, off)
print(f"checked {checked} resorts, mismatches {bad}")
nets = sorted(t["income"]-t["expenses"] for t in lt.values())
print("staging net/day after v2 tick: p25 %.1fk med %.1fk p75 %.1fk max %.1fk; losing %d/%d" % (nets[len(nets)//4]/1e3, nets[len(nets)//2]/1e3, nets[3*len(nets)//4]/1e3, nets[-1]/1e3, sum(n<0 for n in nets), len(nets)))
print("user1:", {k: lt[1][k] for k in ("demand","visitors","lift_capacity","tickets","buildings")}, "tournament visitors", tourn.get(1,0))
EOF

