async function post(url, extra) {
  const t = new DOMParser().parseFromString(await (await fetch('/energy', {credentials: 'same-origin'})).text(), 'text/html');
  const c = t.querySelector('form input[name="csrf_test_name"]');
  const fd = new FormData(); fd.append(c.name, c.value); for (const k in extra) fd.append(k, extra[k]);
  const r = await fetch(url, {method: 'POST', body: fd, credentials: 'same-origin'});
  const d = new DOMParser().parseFromString(await r.text(), 'text/html');
  return {msg: [...d.querySelectorAll('[role=alert],[role=status],.alert')].map(e => e.textContent.trim().replace(/\s+/g, ' '))[0], cash: d.body.innerText.match(/[\d,]+ €/)?.[0]};
}
const first = await post('/energy/build', {source_type: 'grid'});
const second = await post('/energy/build', {source_type: 'grid'});
const page = new DOMParser().parseFromString(await (await fetch('/energy', {credentials: 'same-origin'})).text(), 'text/html');
const gridCard = [...page.querySelectorAll('.card')].find(c => c.textContent.includes('Power Grid Connection') && c.textContent.includes('Pays back'));
const solar = [...page.querySelectorAll('.card')].find(c => c.textContent.includes('QA Solar'));
const water = new DOMParser().parseFromString(await (await fetch('/water', {credentials: 'same-origin'})).text(), 'text/html');
({first, second, gridButton: gridCard?.querySelector('button')?.textContent.trim(), solarLine: solar?.innerText.match(/Saves[^\n]*/)?.[0], waterTop: [...water.querySelectorAll('.card .text-2xl')].map(e => e.textContent.trim()).slice(0, 4), waterBuild: [...water.querySelectorAll('.card dd')].map(e => e.textContent.trim()).slice(0, 5)})

