const page = document;
const firstForm = page.querySelector('form[action*="/achievements/claim/"]');
const id = firstForm.action.split('/').pop();
const csrf = firstForm.querySelector('input[name="csrf_test_name"]').value;
async function post(url, token) { const fd = new FormData(); fd.append('csrf_test_name', token); const r = await fetch(url, {method: 'POST', body: fd, credentials: 'same-origin'}); const d = new DOMParser().parseFromString(await r.text(), 'text/html'); return {msg: [...d.querySelectorAll('[role=alert],[role=status],.alert')].map(e => e.textContent.trim().replace(/\s+/g, ' '))[0], cash: d.body.textContent.match(/[\d,]+ €/)?.[0], token: d.querySelector('input[name="csrf_test_name"]')?.value}; }
const one = await post('/achievements/claim/' + id, csrf);
const again = await post('/achievements/claim/' + id, one.token);
const all = await post('/achievements/claim-all', again.token);
const allAgain = await post('/achievements/claim-all', all.token);
const p = new DOMParser().parseFromString(await (await fetch('/achievements', {credentials: 'same-origin'})).text(), 'text/html');
const nightLink = new DOMParser().parseFromString(await (await fetch('/night-skiing', {credentials: 'same-origin'})).text(), 'text/html');
({one: one.msg + ' | ' + one.cash, again: again.msg, all: all.msg + ' | ' + all.cash, allAgain: allAgain.msg, sections: [...p.querySelectorAll('.ach-group h2')].map(h => h.textContent.trim().replace(/\s+/g, ' ')), earned: [...p.querySelectorAll('.text-2xl')].map(e => e.textContent.trim().replace(/\s+/g,' ')).slice(1, 4), nightSkiingLocked: /locked|Unlock/i.test(nightLink.querySelector('main')?.textContent.slice(0, 400) || ''), nightTitle: nightLink.title})

