async function post(url, data) {
  const t = new DOMParser().parseFromString(await (await fetch('/settings', {credentials: 'same-origin'})).text(), 'text/html');
  const fd = new FormData(); fd.append('csrf_test_name', t.querySelector('input[name="csrf_test_name"]').value); for (const k in data) fd.append(k, data[k]);
  const r = await fetch(url, {method: 'POST', body: fd, credentials: 'same-origin'});
  const d = new DOMParser().parseFromString(await r.text(), 'text/html');
  return {url: r.url.replace(location.origin, ''), msg: [...d.querySelectorAll('[role=alert],[role=status],.alert')].map(e => e.textContent.trim().replace(/\s+/g, ' '))[0], codeField: !!d.querySelector('form[action$="/account/password"] input[name=code]')};
}
