4	
5	/**
6	 * Energy and water rules, shared by the nightly tick and the /energy and /water pages.
7	 * Sources (resource_types) produce a fixed amount per day while active; any demand above
8	 * that is bought from the municipal grid / water network at the tariff.
9	 */
10	class Utilities
11	{
12	    public const GRID_TARIFF = 0.25;   // EUR per kWh imported
13	    public const WATER_TARIFF = 0.01;  // EUR per litre imported
14	
15	    /** Daily energy draw: lifts by type per metre, buildings by level, per lit night-skiing area */
16	    public const LIFT_KWH_PER_M = ['button' => 0.4, 'chair_fixed' => 0.8, 'chair_detach' => 1.0, 'gondola' => 1.4, 'cable_car' => 1.8];
17	    public const BUILDING_KWH = [1 => 20, 2 => 40, 3 => 80];
18	    public const DRAW_NIGHT_LIGHT = 250;
19	
20	    /** Most of a source type one resort may own (there's only one connection to the grid) */
21	    public const LIMIT = ['grid' => 1];
22	
23	    /** Source types for 'energy' or 'water', keyed by resource_key */
24	    public static function config(string $category): array
25	    {
26	        static $cache = [];
27	        if (!isset($cache[$category])) {
28	            $cache[$category] = [];
29	            foreach (db_connect()->table('resource_types')->where('category', $category)->orderBy('sort_order')->get()->getResultArray() as $r) {
30	                $cache[$category][$r['resource_key']] = [
31	                    'label' => $r['label'], 'icon' => $r['icon'], 'cost' => (int) $r['cost'], 'build_days' => (int) $r['build_days'],
32	                    'capacity' => (int) $r['capacity'], 'output' => (int) $r['output'], 'upkeep' => (int) $r['upkeep'], 'decay' => (float) $r['decay_rate'],
33	                ];
34	            }
35	        }
36	        return $cache[$category];
37	    }
38	
39	    public static function liftKwh(string $type, int $meters): int
40	    {
41	        return (int) round($meters * (self::LIFT_KWH_PER_M[$type] ?? 0.8));
42	    }
43	
44	    /**
45	     * Energy draw (kWh/day) by consumer: running snowmakers' rated energy_kwh, lit night-skiing
46	     * areas, open lifts (rows with subtype and length_meters) and open buildings (rows with level).
47	     */
48	    public static function energyDemand(array $activeSnowmakers, int $lights, array $openLifts, array $openBuildings): array
49	    {
50	        $d = [
51	            'snowmaking' => (int) array_sum(array_column($activeSnowmakers, 'energy_kwh')),
52	            'night_skiing' => $lights * self::DRAW_NIGHT_LIGHT,
53	            'lifts' => array_sum(array_map(fn($l) => self::liftKwh($l['subtype'] ?? '', (int) ($l['length_meters'] ?? 0)), $openLifts)),
54	            'buildings' => array_sum(array_map(fn($b) => self::BUILDING_KWH[(int) ($b['level'] ?? 1)] ?? 20, $openBuildings)),
55	        ];
56	        return $d + ['total' => array_sum($d)];
57	    }
58	
59	    public static function waterDemand(array $activeSnowmakers): int
60	    {
61	        return (int) array_sum(array_column($activeSnowmakers, 'water_liters'));
62	    }

47	
48	    /** Condition points one pass restores, better with experienced operators */
49	    public static function restore(array $operators): int
50	    {
51	        $avgLevel = $operators ? array_sum(array_map(fn($o) => (int) ($o['level'] ?? 1), $operators)) / count($operators) : 1;
52	        return (int) min(self::RESTORE_MAX, round(self::RESTORE_BASE + self::RESTORE_PER_LEVEL * $avgLevel));
53	    }
54	
55	    /** Slopes grooming can work on: open ones, and ones closed because they wore down to 0% (grooming reopens them) */
56	    public static function groomable(array $slope): bool
57	    {
58	        return in_array($slope['status'] ?? 'open', ['open', 'broken'], true) && (int) $slope['condition_pct'] < 100;
59	    }
60	
61	    /** The slopes a run of $capacity passes should groom, worst first */
62	    public static function pick(array $slopes, int $capacity): array
63	    {
64	        $due = array_values(array_filter($slopes, [self::class, 'groomable']));
65	        usort($due, fn($a, $b) => (int) $a['condition_pct'] <=> (int) $b['condition_pct']);
66	        return array_slice($due, 0, max(0, $capacity));
67	    }
68	
69	    public static function extraRunCost(array $slope): int
70	    {
71	        return (int) round(max(1, (int) ($slope['length_meters'] ?? 0)) * self::EXTRA_RUN_PER_M);
72	    }

