cd /opt/1panel/www/sites/skiv2/ci4; cat > writable/smtpcheck.php <<'"'"'EOF'"'"'
<?php
$env = file_get_contents("/www/sites/skiv2/ci4/.env");
preg_match("/^\s*SMTP_PASSWORD\s*=\s*(.*)$/m", $env, $m);
$pass = trim($m[1] ?? ""); $pass = trim($pass, "\"'"'"'");
$fp = stream_socket_client("ssl://smtp.hostinger.com:465", $errno, $errstr, 15);
if (!$fp) { echo "connect failed: $errstr\n"; exit; }
$r = fn() => fgets($fp, 512);
$w = function ($s) use ($fp) { fwrite($fp, $s . "\r\n"); };
echo "banner: " . trim($r());
$w("EHLO ski-manager.net"); while (($l = $r()) !== false) { if (preg_match("/^250 /", $l)) break; }
$w("AUTH LOGIN"); $r(); $w(base64_encode("contact@ski-manager.net")); $r(); $w(base64_encode($pass));
echo "\nauth reply: " . trim($r()) . "\n"; $w("QUIT"); fclose($fp);
EOF
docker exec PHP php /www/sites/skiv2/ci4/writable/smtpcheck.php; rm writable/smtpcheck.php'

